/// Computes the minimum number of inspectors needed to cover `n` items
/// when each inspector has a symmetric coverage radius of `d`.
/// Each inspector covers up to `2*d + 1` consecutive items.
/// This is simply the ceiling of `n / (2*d + 1)`.
fn min_inspectors(n: i8, d: i8) -> i8 {
    // Maximum items one inspector can cover
    let coverage = 2 * d + 1;
    // Compute ceil(n / coverage) via integer arithmetic
    (n + coverage - 1) / coverage
}

